11	import { detailedProperty, serveProperty, type DetailedProperty } from '@/test/properties';
12	import { renderRoute } from '@/test/render';
13	
14	/** In-memory backend for the list, detail and delete operations, sharing one set of rows. */
15	function serveBackend(rows: DetailedProperty[], deleted: string[] = []) {
16	  return [
17	    graphql.query<PropertiesQuery>('Properties', () =>
18	      HttpResponse.json({ data: { __typename: 'Query', properties: rows } }),
19	    ),
20	    serveProperty(rows),
21	    graphql.mutation<DeletePropertyMutation, DeletePropertyMutationVariables>(
22	      'DeleteProperty',
23	      ({ variables }) => {
24	        const id = String(variables.id);
25	        const index = rows.findIndex((row) => row.id === id);
26	        deleted.push(id);
27	        if (index === -1) {
28	          return HttpResponse.json({
29	            data: {
30	              __typename: 'Mutation',
31	              deleteProperty: {
32	                __typename: 'PropertyNotFoundError',
33	                message: 'Property not found.',
34	                id,
35	              },
36	            },
37	          });
38	        }
39	        rows.splice(index, 1);
40	        return HttpResponse.json({
41	          data: {
42	            __typename: 'Mutation',
43	            deleteProperty: { __typename: 'DeletePropertySuccess', id },
44	          },
45	        });
46	      },
47	    ),
48	  ];
49	}
