57	describe('delete property', () => {
58	  it('S6.6 asks for confirmation and deletes nothing when cancelled', async () => {
59	    const deleted: string[] = [];
60	    server.use(...serveBackend([detailedProperty()], deleted));
61	    renderRoute('/properties/property-1');
62	
63	    const { user, dialog } = await openDeleteDialog();
64	
65	    expect(within(dialog).getByText('Delete this property?')).toBeInTheDocument();
66	    expect(
67	      within(dialog).getByText(/15528 E Golden Eagle Blvd, Fountain Hills, AZ 85268/),
68	    ).toBeInTheDocument();
69	    await user.click(within(dialog).getByRole('button', { name: 'Keep property' }));
70	
71	    expect(screen.queryByRole('alertdialog')).not.toBeInTheDocument();
72	    expect(deleted).toEqual([]);
73	  });
74	
75	  it('S6.6 removes the property from the list and its detail route shows "not found"', async () => {
76	    const rows = [detailedProperty(), detailedProperty({ id: 'property-2', street: '1 Main St' })];
77	    const deleted: string[] = [];
78	    server.use(...serveBackend(rows, deleted));
79	    const { router } = renderRoute('/properties/property-1');
80	
81	    const { user, dialog } = await openDeleteDialog();
82	    await user.click(within(dialog).getByRole('button', { name: 'Delete property' }));
83	
84	    expect(await screen.findByText('1 Main St')).toBeInTheDocument();
85	    expect(router.state.location.pathname).toBe('/');
86	    expect(screen.queryByText('15528 E Golden Eagle Blvd')).not.toBeInTheDocument();
87	    expect(deleted).toEqual(['property-1']);
88	
89	    await router.navigate('/properties/property-1');
90	
91	    expect(await screen.findByText('Property not found')).toBeInTheDocument();
92	  });
93	
94	  it('S6.6 treats an already-deleted property as gone and returns to the list', async () => {
95	    const rows = [detailedProperty()];
96	    server.use(...serveBackend(rows));
97	    const { router } = renderRoute('/properties/property-1');
98	    await screen.findByRole('heading', { name: '15528 E Golden Eagle Blvd' });
99	    rows.length = 0; // deleted elsewhere after the page loaded
