import { createBrowserRouter, type RouteObject } from 'react-router';
import { HomeRoute } from './routes/home';
import { NewPropertyRoute } from './routes/new-property';
import { PropertyRoute } from './routes/property';
import { RootLayout } from './routes/root-layout';

export const routes: RouteObject[] = [
  {
    path: '/',
    Component: RootLayout,
    children: [
      { index: true, Component: HomeRoute },
      { path: 'properties/new', Component: NewPropertyRoute },
      { path: 'properties/:id', Component: PropertyRoute },
    ],
  },
];

export const router = createBrowserRouter(routes);

import { defineConfig } from 'vitest/config';
import { TEST_DATABASE_URL } from './test/test-database-url.ts';

// Tests never use the dev database or the real Weatherstack (CLAUDE.md "Tests").

export default defineConfig({
  test: {
    env: {
      DATABASE_URL: TEST_DATABASE_URL,
      TEST_DATABASE_URL,
      WEATHERSTACK_BASE_URL: 'http://weatherstack.test',
      WEATHERSTACK_ACCESS_KEY: '[REDACTED]',
    },
    setupFiles: ['test/setup.ts'],
    projects: [
      {
        extends: true,
        test: {
          name: 'unit',
          include: ['src/**/*.test.ts', 'test/**/*.test.ts'],
          exclude: ['**/*.int.test.ts'],
        },
      },
      {
        extends: true,
        test: {
          name: 'integration',
          include: ['src/**/*.int.test.ts', 'test/**/*.int.test.ts'],
          globalSetup: ['test/global-setup.int.ts'],
          // One shared database: run integration files one at a time.
          fileParallelism: false,
        },
      },
    ],
  },
});

import { Link, Outlet } from 'react-router';
import { Button } from '@/components/ui/button';

export function RootLayout() {
  return (
    <div className="min-h-svh bg-background">
      <header className="border-b">
        <div className="mx-auto flex max-w-3xl items-center justify-between px-4 py-3">
          <Link to="/" className="font-heading text-lg font-semibold">
            Covertree properties
          </Link>
          <Button asChild size="sm">
            <Link to="/properties/new">New property</Link>
          </Button>
        </div>
      </header>
      <main className="mx-auto max-w-3xl px-4 py-8">
        <Outlet />
      </main>
    </div>
  );
}

